# ---------------------------------------------------------------- 颜色输出

class C:
    RED = "\033[91m"
    YELLOW = "\033[93m"
    BLUE = "\033[94m"
    GREEN = "\033[92m"
    BOLD = "\033[1m"
    RESET = "\033[0m"

def _tag(level):
    if level == "ERROR":
        return f"{C.RED}[ERROR]{C.RESET}"
    elif level == "WARN":
        return f"{C.YELLOW}[WARN]{C.RESET} "
    elif level == "INFO":
        return f"{C.BLUE}[INFO]{C.RESET} "
    return f"{C.GREEN}[OK]{C.RESET}  "

# ---------------------------------------------------------------- 辅助

def _rel(path):
    """绝对路径 → 相对 wiki/ 的路径"""
    return os.path.relpath(path, K.WIKI).replace("\\", "/")

def _page_type(rel_path):
    """从相对路径推断类型"""
    d = rel_path.split("/")[0]
    mapping = {"sources": "source", "concepts": "concept", "entities": "entity",
               "topics": "topic", "outputs": "output"}
    return mapping.get(d, "unknown")

def _load_all_pages():
    """加载所有 wiki 页面，返回 {rel_path: (fm_dict, body, full_path)}

    2026-09-22 增补：**把 wiki 根下的元页面（index.md / log*.md）也纳入加载**。
    此前只加载 PAGE_DIRS（sources/concepts/entities/topics/outputs），导致
    `index.md` 的链接**完全不计入入链图** ⇒ 所有「只被 index 收录、正文无互链」
    的页面（历史上是 7 个 outputs/lint-report）被**永久误报为孤立页**。
    index.md 是官方索引、其链接是真实入链，必须计入。
    """
    pages = {}
    for fp in K.iter_page_files():
        rel = _rel(fp)
        text = K.read_text(fp)
        fm_raw, body = K.split_frontmatter(text)
        fm = K.parse_frontmatter(fm_raw)
        pages[rel] = (fm, body, fp)
    # 补充：wiki 根下的元页面（index.md、log.md、log_ops.md、log_insights.md）
    for fn in ("index.md", "log.md", "log_ops.md", "log_insights.md"):
        fp = os.path.join(K.WIKI, fn)
        if not os.path.isfile(fp):
            continue
        rel = _rel(fp)
        if rel in pages:
            continue
        text = K.read_text(fp)
        fm_raw, body = K.split_frontmatter(text)
        fm = K.parse_frontmatter(fm_raw)
        pages[rel] = (fm, body, fp)
    return pages

def _page_name(rel_path):
    """从相对路径取页面名（无目录无后缀）"""
    base = os.path.basename(rel_path)
    return base.rsplit(".", 1)[0]

def _build_name_set(pages):
    """所有页面名集合（用于 wikilink 解析）"""
    names = set()
    for rel in pages:
        names.add(_page_name(rel))
    return names

# 指向 vault 真实文件（而非 wiki 页面）的链接前缀。
# 这些链接的目标是 raw/ 等目录下的文件，既不是 wiki 页面，也没有 .md 页面名，
# 因此必须走文件系统校验，不能混入页面名集合解析。
_ASSET_LINK_PREFIXES = ("raw/", "tools/", "assets/", ".")


# wiki/ 下的元页面（内容型页面之外的长期维护文件），它们也是合法的 wikilink 目标
_META_PAGES = ("index", "log", "log_ops", "log_insights")


def _resolve_target(t, name_set, alias_map):
    """把 wikilink 目标解析成页面名，找不到返回 None。

    仅处理**指向 wiki 页面**的链接。指向 vault 文件的资源型链接
    （如 [[raw/clippings/x.md]]）在此返回 None，由 _resolve_vault_file 负责，
    调用方须先判定链接种类再选解析器——否则会把真实存在的 raw 回链误报为 broken。

    容错两种写法（2026-09-22 补）：
      [[entities/潘锋.md]] —— 带 .md 后缀的页面链接（name_set 只存无后缀名）
      [[index.md]]         —— wiki/ 下的元页面
    """
    t = t.replace("\\|", "|").split("|")[0].split("#")[0].strip()
    t = t.replace("\\", "").split("/")[-1]
    # 去掉可选的 .md 后缀——name_set 存的是无后缀页面名
    if t.endswith(".md"):
        t = t[:-3]
    if t in name_set:
        return t
    low = t.lower()
    if low in alias_map:
        return alias_map[low]
    # wiki/ 元页面：链接写作 [[index]]/[[index.md]]/[[log]] 均视为有效
    if low in _META_PAGES:
        return low
    return None


# 「点开看图」类交互式别名的指纹——带这类别名的图片 wikilink 是**有意的超链接**，
# 不是漏写 `!`。2026-09-25 实测：本检查曾据此误报 31 处「错误」，真值 0。
_HYPERLINK_ALIAS_RE = re.compile(r"打开|查看|看图|点开|点击|🖼|👁|🔍|open", re.I)


def _is_vault_file_link(link):
    """判断一条 wikilink 是否指向 vault 真实文件（而非 wiki 页面）。

    ```text
    [[raw/clippings/x.md]]      → True  （raw 回链，最典型的资源型链接）
    [[raw/AI for Materials/x]]  → True
    [[tools/kb_search.py]]      → True
    [[concepts/固态电解质]]       → False （wiki 页面，走页面名解析）
    [[sources/2026-xxx]]        → False
    ```
    """
    t = link.replace("\\|", "|").split("|")[0].split("#")[0].strip()
    t = t.replace("\\", "")
    return t.startswith(_ASSET_LINK_PREFIXES)


def _resolve_vault_file(link, vault_root):
    """校验资源型 wikilink 是否指向真实存在的文件，返回规范化相对路径或 None。

    容错三种常见写法（Obsidian 自己也能识别）：
      1. [[raw/x.md]]        —— 带后缀，直接查
      2. [[raw/x]]           —— 省略 .md，补后缀再查
      3. [[../raw/x.md]]     —— 带相对路径前缀（本库不用，但便宜地容忍）

    本库已知陷阱：文件名含中文弯引号、全角标点、空格，故一律走
    os.path.exists 的文件系统查询，**不做任何文件名归一化/模糊匹配**——
    归一化会把"链接确实写错了"的行也放过，那正是 lint 该抓的东西。
    """
    t = link.replace("\\|", "|").split("|")[0].split("#")[0].strip()
    t = t.replace("\\", "").strip()

    # 去掉可能的前导 ./ 与 ../ （后者逐级上溯）
    candidates = []
    if t.startswith("../"):
        base = vault_root
        while t.startswith("../"):
            base = os.path.dirname(base)
            t = t[3:]
        candidates.append(os.path.join(base, t))
    elif t.startswith("./"):
        candidates.append(os.path.join(vault_root, t[2:]))
    else:
        candidates.append(os.path.join(vault_root, t))

    # 省略 .md 后缀的写法
    for c in list(candidates):
        if not c.endswith(".md"):
            candidates.append(c + ".md")

    for c in candidates:
        if os.path.exists(c):
            return os.path.relpath(c, vault_root).replace("\\", "/")
    return None

# ---------------------------------------------------------------- log.md 解析

def _parse_log_dates(log_path, days):
    """从 log.md 提取最近 N 天内新建的 source 页面名"""
    if not os.path.exists(log_path):
        return []
    text = K.read_text(log_path)
    cutoff = datetime.now() - timedelta(days=days)
    # 匹配 ## [YYYY-MM-DD] 格式的日志条目
    entries = re.findall(r"^## \[(\d{4}-\d{2}-\d{2})\]\s+.*$", text, flags=re.M)
    recent_dates = []
    for d in entries:
        try:
            dt = datetime.strptime(d, "%Y-%m-%d")
            if dt >= cutoff:
                recent_dates.append(d)
        except ValueError:
            continue
    if not recent_dates:
        return []
    # 从日志中提取 "新建页" 后面列出的页面名
    new_pages = []
    date_pattern = "|".join(re.escape(d) for d in set(recent_dates))
    # 匹配形如 "新建页 N：page1、page2、page3" 或 "- 新建页 1：xxx"
    for m in re.finditer(
        rf"^## \[(?:{date_pattern})\].*?(?=^## \[|\Z)",
        text, flags=re.M | re.S
    ):
        block = m.group(0)
        # 找 "新建页" 行
        for pm in re.finditer(r"新建页\s*\d*[：:]\s*(.+)", block):
            names_str = pm.group(1).strip()
            # 按中文逗号或顿号分割
            for name in re.split(r"[、，,]", names_str):
                name = name.strip().strip("`").strip()
                if name:
                    new_pages.append(name)
    return new_pages

# ---------------------------------------------------------------- Quick Lint 检查项

def check_frontmatter(rel, fm, body):
    """检查 1: frontmatter 完整性"""
    issues = []
    required = ["created", "updated", "type", "tags", "summary"]
    for field in required:
        val = fm.get(field)
        if val is None or (isinstance(val, str) and not val.strip()):
            issues.append(("ERROR", f"missing required frontmatter field: {field}"))
        elif isinstance(val, list) and len(val) == 0:
            issues.append(("ERROR", f"empty frontmatter field: {field}"))
    return issues

def check_source_specific(rel, fm, body):
    """检查 2: source 页专项检查"""
    issues = []
    # source_reliability
    sr = fm.get("source_reliability")
    if not sr or (isinstance(sr, str) and not sr.strip()):
        issues.append(("ERROR", "missing source_reliability"))
    # si_status (warning 级别)
    si = fm.get("si_status")
    if not si:
        # 也检查 source_reliability 里是否提到了 SI
        sr_text = str(fm.get("source_reliability", "")).lower()
        # ⚠️ 旧判据是 `"si" not in sr_text` —— 这是**子串匹配**，会把与 SI 无关的
        #    英文词当成已交代：实测有 9 页被压制，其中 2 页的真因是
        #    `NIT Silchar`（印度国家技术学院）、`Faraday Discussions`（刊名）、
        #    `general discussion transcript`。现在改用词边界 + 中文词。
        if not re.search(r"(?i)\bSI\b|补充材料|补充数据|supplementary", sr_text):
            issues.append(("WARN", "si_status not set"))
    # "honest boundaries" 和 "critical assessment" 章节
    headings = [h.lower() for h in K.extract_headings(body)]
    has_honest = any("honest" in h or "诚实" in h or "边界" in h or "局限" in h for h in headings)
    has_critical = any("critical" in h or "批判" in h or "评估" in h or "判" in h for h in headings)
    if not has_honest:
        issues.append(("WARN", "missing 'honest boundaries' / 局限性 section"))
    if not has_critical:
        issues.append(("WARN", "missing 'critical assessment' / 批判性评估 section"))
    # raw/ 反向链接
    # 🔴 2026-10-11：**不能只看 `raw/`**。`raw/_park` 解散后，被判跑题/重复而隔离的素材迁到了
    #    `_archive/retired/quarantine/`，于是「素材只在归档层」成了**合法**状态。旧判据把它读成
    #    "no raw/ backlink found"——这句话**事实错误**：素材在库内，只是不在 `raw/` 下，
    #    后果是该页被当成"未摄入"。这正是本库记录过的事故型缺省值「库内 = raw/」（§已知陷阱 1b）。
    #    新判据分三态：有 raw/ 回链=正常；仅归档层回链=**WARN**（素材已隔离，需人判断该页是否
    #    也该隔离）；两者皆无=仍为 ERROR（真的没有出处）。
    srcs = str(fm.get("sources", ""))
    has_raw_link = bool(re.search(r"\[\[raw/", body)) or bool(re.search(r"\[\[raw/", srcs))
    has_arch_link = (bool(re.search(r"\[\[_archive/", body))
                     or bool(re.search(r"\[\[_archive/", srcs)))
    if not has_raw_link:
        if has_arch_link:
            issues.append(("WARN", "provenance only in _archive/ "
                                   "(material quarantined; consider whether this page belongs there too)"))
        else:
            issues.append(("ERROR", "no raw/ backlink found"))
    return issues

def _classify_link(link, name_set, alias_map, vault_root):
    """判定链接是否有效，返回 (kind, resolved)。

    kind: "page"   —— wiki 页面，resolved 为页面名
          "file"   —— vault 真实文件，resolved 为相对路径
          "broken" —— 两者都不是

    解析顺序（先页面后文件）：
      1. 前缀明确的资源链接（raw/ tools/ assets/ ./ ../）→ 直接查文件系统
      2. 页面名解析（含去 .md 后缀与 wiki 元页面）
      3. 兜底：vault 根目录下的真实文件（如 [[CLAUDE.md]]）→ 查文件系统
    第 3 步让"确有文件但既非页面也非已知资源前缀"的链接不被误报，
    同时保留对真正写错路径的报错（os.path.exists 为 False 仍判 broken）。
    """
    if _is_vault_file_link(link):
        r = _resolve_vault_file(link, vault_root)
        return ("file", r) if r else ("broken", None)
    r = _resolve_target(link, name_set, alias_map)
    if r:
        return ("page", r)
    # 兜底：查 vault 根下的真实文件（[[CLAUDE.md]]、[[README.md]] 等）
    r = _resolve_vault_file(link, vault_root)
    return ("file", r) if r else ("broken", None)


def check_wikilinks(rel, fm, body, name_set, alias_map, vault_root=K.VAULT):
    """检查 3: wikilink 有效性

    页面链接查页面名集合，资源链接（[[raw/...]] 等）查文件系统——
    两者混用会把 429 条真实存在的 raw 回链全部误报为 broken（2026-09-22 修复）。

    2026-09-22 增补：另查三类「语法合法但静默失效」的写法（原版全部漏检，
    靠自建审计脚本才发现，全库分别有 1390 / 425 / 7 处）：
      · 目标尾部带 `\\` 或 `/` → Obsidian 点不开（[[sources/X\\]]）
      · 图片写成 [[fig.png]] / !![[fig.png]] → 不渲染
    """
    issues = []
    outlinks = K.extract_outlinks(body)
    for link in outlinks:
        raw_target = link.split("|")[0].strip()
        # —— 新增：尾部污染字符 ——
        if raw_target.endswith("\\") or raw_target.endswith("/"):
            issues.append(("ERROR",
                           f"wikilink 目标尾部含污染字符（Obsidian 点不开）: [[{link}]]"))
        kind, _ = _classify_link(link, name_set, alias_map, vault_root)
        if kind == "broken":
            issues.append(("ERROR", f"broken wikilink: [[{link}]]"))
    # —— 图片 wikilink（2026-09-25 改：**直接在 body 上扫，不经 extract_outlinks**）——
    #
    # ⚠️ 为什么不能复用 outlinks：`extract_outlinks` **刻意丢弃别名**（建图只需要目标），
    #    而本检查必须看别名才能判意图（见下）。2026-09-25 实测：走 outlinks 时
    #    别名永远是空 ⇒ 交互式超链接被误报成「漏写 `!`」（误报 31 处，真值 0）。
    #
    # ⚠️ 为什么「图片 wikilink」不等于缺陷：**本库大量图片 wikilink 是有意的
    #    「点开看图」超链接**（`[[x.png|🖼 打开]]`、表格里写 `\|🖼 打开`），
    #    改成 `![[ ]]` 会让图片在正文/表格里直接铺开、**破坏排版**。
    #    ⇒ 判据：**别名是交互式措辞（打开/查看/看图/点开/🖼）⇒ 有意超链接，跳过**；
    #      只有「无别名」才**可能**是漏写 `!`（仍可能有别的意图 ⇒ 只报 WARN 让人判）。
    # 🔴 2026-10-10：**必须先剔代码块/行内代码**。
    #    lint 报告与 QC 报告里会**演示**「坏写法长什么样」（`[[fig.png]]` / `!![[x]]`
    #    写在反引号或围栏里），不剔就会把示例当真链接。实测差异：
    #    图片 WARN 21 → 19（2 条来自代码块）、!![[ 2 → 1（1 条来自代码块）。
    #    这与 CLAUDE.md 记录的「4 号事故」（34 处图片语法错误，真值 0）同型，
    #    公共实现已收敛到 kb_lib.strip_code。
    body = K.strip_code(body)
    for m in re.finditer(
            r"(?<!!)\[\[([^\]\n]*?\.(?:png|jpg|jpeg|gif|webp|svg))((?:\\?\|[^\]]*)?)\]\]",
            body, re.I):
        tgt, alias = m.group(1), m.group(2)
        if _HYPERLINK_ALIAS_RE.search(alias):
            continue
        issues.append(("WARN",
                       f"图片 wikilink 未带交互式别名（可能漏写 `![[ ]]`，"
                       f"也可能是有意超链接——请人工确认）: [[{tgt}{alias}]]"))
    # —— 双/三感叹号图片 ——
    for m in re.finditer(r"!{2,}\[\[", body):
        issues.append(("WARN", "图片嵌入写成 !![[...]] 或更多感叹号，Obsidian 不渲染"))
        break
    return issues


def check_raw_backlink_style(rel, fm, body, *a, **kw):
    """检查 3b: raw 回链写法（2026-09-22 新增）

    CLAUDE.md 声明 `sources:` 首条的 raw 回链是**摄入统计的唯一依据**。
    历史上出现过被反引号包裹的裸文件名写法：
        sources:
          - "`10_1038_xxx.md`"        ← 既非 wikilink，又丢 raw/ 前缀
    全库曾达 **425 处 / 364 页**，全部静默失效。此检查防止复发。

    注：fm 传入的是已解析的 dict，故此处字符串化后再查反引号。
    """
    issues = []
    if not isinstance(fm, dict):
        return issues
    srcs = fm.get("sources") or []
    if isinstance(srcs, str):
        srcs = [srcs]
    for v in srcs:
        s = str(v)
        if "`" in s and "[[" not in s:
            inner = s.strip('"').strip("'").strip("`").strip()
            if inner.endswith(".md") or inner.endswith(".pdf"):
                issues.append(("ERROR",
                               f"sources 回链写成反引号裸文件名（非 wikilink，摄入统计看不到）: {s[:70]}"))
    return issues


def check_yaml_parseable(rel, fm, body, *a, **kw):
    """检查 3c: source 页回链存在性（2026-09-22 新增）

    本函数原本用于校验 frontmatter 能否被 YAML 解析。但 _load_all_pages 已先
    用 YAML 解析过、解析失败的页根本进不到这里——所以「解析失败」在上游表现为
    **页面被静默跳过**，而不是本函数能捕获的错误。

    因此改为在下游做两件事：
      1) 检查 source 页的 `sources:` 里**至少有一条 raw/ 回链**（摄入统计依据）；
      2) 检查 `si_status` 是否为已知取值（防止拼错导致统计口径分裂）。
    """
    issues = []
    if not isinstance(fm, dict):
        return issues
    if fm.get("type") != "source":
        return issues
    srcs = fm.get("sources") or []
    if isinstance(srcs, str):
        srcs = [srcs]
    has_raw = any("[[raw/" in str(v) for v in srcs)
    if not has_raw:
        # 允许以 [[sources/...]] 页面互链形式存在（少量剪藏页如此）
        has_raw = any("[[raw/" in str(v) or "raw/" in str(v) for v in srcs)
    if not has_raw:
        issues.append(("WARN", "source 页 sources: 字段无 raw/ 回链（摄入统计依据缺失）"))
    si = fm.get("si_status")
    if si is not None and str(si).strip():
        # 白名单走 kb_lib 的**唯一一份**（此前本文件 4 值、kb_lint_deep 5 值，
        # 同一页在两个校验器里可能一个合法一个非法）。
        if not K.si_status_ok(si):
            issues.append(("WARN",
                           f"si_status 取值非规范: {si!r}（应为 {K.SI_STATUS_HINT}）"))
    return issues


def check_frontmatter_parse_all(vault_root=K.VAULT):
    """检查 0: 全库 frontmatter 可解析性（2026-09-22 新增，deep 专用）

    必须在**未解析的原始文本**上做，否则非法 YAML 的页会在 _load_all_pages
    里被静默跳过、永远查不出来。全库曾有 49 页因此丢失全部元数据。
    """
    import glob as _glob
    try:
        import yaml
    except ImportError:
        return []
    issues = []
    for fp in _glob.glob(os.path.join(vault_root, "wiki", "**", "*.md"), recursive=True):
        if ".index" in fp or ".claude-rename" in fp:
            continue
        try:
            t = K.read_text(fp)
        except Exception:
            continue
        m = re.match(r"^---\r?\n(.*?)\r?\n---", t, re.S)
        if not m:
            continue
        try:
            d = yaml.safe_load(m.group(1))
            if d is not None and not isinstance(d, dict):
                issues.append((_rel(fp), "ERROR", "frontmatter 不是 YAML 映射"))
        except Exception as e:
            issues.append((_rel(fp), "ERROR",
                           f"frontmatter YAML 解析失败（该页元数据全部静默丢失）: {str(e).splitlines()[0][:90]}"))
    return issues

def check_degree(rel, fm, body, name_set, alias_map, inbound_map, vault_root=K.VAULT):
    """检查 4: 出度/入度检查

    出度只计**指向 wiki 页面**的链接：raw 回链/附件属资源引用，
    不是知识图谱的边，计入会让"只在来源页堆 raw 链接"的页面伪装成高连接度。
    """
    issues = []
    outlinks = K.extract_outlinks(body)
    out_degree = sum(
        1 for l in outlinks
        if _classify_link(l, name_set, alias_map, vault_root)[0] == "page"
    )
    page_name = _page_name(rel)
    in_degree = len(inbound_map.get(page_name, set()))
    if out_degree < 2:
        issues.append(("WARN", f"low out-degree: {out_degree} (need >= 2)"))
    if in_degree < 1:
        issues.append(("ERROR", f"0 inbound links (orphan)"))
    return issues

def check_warning_callout(rel, fm, body):
    """检查 5: source 页 warning 标记 —— **已废弃，恒返回空**。

    🔴 2026-10-10 的结论：这是一个**没有区分力的检查**，两种写法都不行，只能撤掉。

    原判据 `"⚠️" in body or "⚠" in body`：第二个条件完全包含第一个（同一个字符的
    带/不带变体选择符写法），且本库**全部 503 个 source 页都含 ⚠️**（批判性摄入模板
    要求每页都有 `## 批判性评估`，必然带 ⚠️）⇒ 实测触发 **0 次**，后两个
    `[!warning]` 正则分支也永远改不了结论。**一个永远不报的检查等于没有检查**。

    我一度把它改锚到「页首 25 行内要有 callout」，结果更糟：实测 **402/503 页报警**
    （只有 101 页把 ⚠️ 放在页首），WARN 从 92 涨到 455 —— 噪声直接淹没真信号。
    而且**它本身就是错的规范**：CLAUDE.md §批判性标记 明写
    「标记应**就地贴在具体句子/数字旁**」——并未要求把 callout 放到页首。

    ⇒ 撤掉。真正想抓的那件事（"复述了带限定词的数字却没承接"）已经由
    `check_evidence_inheritance()` 用**锚定具体数字**的方式抓了（那是有区分力的形式）。
    本函数保留为空壳，只为不改动两处调用点；**不要再往里加判据**——
    先证明它能在已知样本上分辨「该报的」与「不该报的」，再开。
    """
    return []


# ---------------------------------------------------------------- Deep Lint 检查项

def check_entity_depth(pages):
    """检查 6: entity 页深度"""
    issues = []
    for rel, (fm, body, fp) in pages.items():
        if _page_type(rel) != "entity":
            continue
        size = os.path.getsize(fp)
        if size < 1536:  # 1.5KB
            issues.append((rel, "INFO", f"entity page too small ({size}B, need >= 1.5KB) — needs-expansion"))
    return issues

def check_topic_coverage(pages):
    """检查 7: concept 关联 >= 8 个 source 但没有 topic 页"""
    issues = []
    # 统计每个 concept 被多少 source 关联
    concept_sources = defaultdict(set)
    topic_names = set()
    for rel, (fm, body, fp) in pages.items():
        ptype = fm.get("type", "")
        if ptype == "topic":
            topic_names.add(_page_name(rel))
        if ptype == "source":
            # 找 source 里链接到的 concept
            outlinks = K.extract_outlinks(body)
            for link in outlinks:
                target = link.replace("\\|", "|").split("|")[0].split("#")[0].strip()
                target = target.replace("\\", "").split("/")[-1]
                # 检查是否是 concept
                concept_rel = f"concepts/{target}.md"
                if concept_rel in pages:
                    concept_sources[target].add(_page_name(rel))
    # 检查哪些 concept 有大量 source 但没有 topic
    #
    # 🔴 阈值必须是**当前规范**，不是 2026-09-22 之前那版。
    #    CLAUDE.md §知识综合与 Topic 页指引 已把「任一 concept ≥8 source 即建 topic」
    #    改成**双闸门**：≥20 个关联 source 且构成独立知识模块；或一个 ≥12 source 的**簇**。
    #    代码若仍按 8 报警，就会与文档打架，而且把 INFO 级提示淹成 WARN：
    #    实测 92 条 WARN 里有 **62 条**来自这条过期阈值（最高一个 concept 关联 89 篇）。
    #    ⇒ 现在只在真正过线时 WARN；8–19 区间降为 INFO（"提示而非缺陷"，与文档一致）。
    TOPIC_HARD = 20        # 独立知识模块口径
    TOPIC_SOFT = 8         # 低于此完全不报（连提示都没有意义）
    for concept, srcs in sorted(concept_sources.items(),
                                key=lambda kv: -len(kv[1])):
        if concept in topic_names:
            continue
        n = len(srcs)
        if n >= TOPIC_HARD:
            issues.append((f"concepts/{concept}.md", "WARN",
                           f"concept linked by {n} sources but has no topic page"
                           f"（≥{TOPIC_HARD} ⇒ 按 CLAUDE.md 双闸门应评估建 topic）"))
        elif n >= TOPIC_SOFT:
            issues.append((f"concepts/{concept}.md", "INFO",
                           f"concept linked by {n} sources, no topic page"
                           f"（8–19 区间，CLAUDE.md 说明**多数应当忽略**）"))
    return issues

# ---------------------------------------------------------------- 证据继承
#
# ⚠️ 设计前必须知道的实测事实（2026-09-25，vault 实测）：
#   「source 页正文含任意 `⚠️`」这个判据**完全没有区分力**——
#   362/362 个 source 页都命中（因为批判性摄入模板要求每页都写
#   `## 批判性评估`，其中必然带 `⚠️`）；即便切掉批判节，仍有 300/362 命中。
#   ⇒ 用「上游有没有 ⚠️」当条件，会把**几乎每一页**都拉进来，
#     结果是噪声淹没信号，最终被人无视（比不检查更糟）。
#
# 因此本检查改为**锚定具体数字**：只有当 concept/topic 页里出现了一个
# **在上游 source 页中带限定标记的相同数字**时，才要求该页给出承接。
# 这是 QC 实证的头号失真类型（Q07 命中率 ~65%）的**可机械判定**形式。

# 「承接」的表述指纹——出现了就算本页已交代限定
_HEDGE_PAT = re.compile(
    r"⚠|单源|仅本(?:课题)?组|未被独立|未经独立|尚无.*(?:复现|验证)|"
    r"自报|无第三方|预印本|二手|体裁提示|范围漂移|信息缺口|"
    r"未做.*(?:对照|验证)|无.*对照|自算|反推|折算",
    re.I)

# 数字提取：>=2 位有效、支持千分位与小数
_NUM_PAT = re.compile(r"\d{1,3}(?:,\d{3})+(?:\.\d+)?|\d+\.\d+|\d{3,}")

# ⚠️ 必须排除的「伪数字」（2026-09-25 实测的假阳性来源）：
#   · **年份**（1900–2099 的整数）—— 出现在 wikilink 文件名、正文纪年里
#     实测：`传输线模型` 仅因正文含 `2026` 就被报，而该数字来自 `[[sources/2026-…]]`
#   · 因此要求命中的数字**不是 4 位年份**，且**不得出现在 wikilink 内部**
_YEAR_RE = re.compile(r"^(?:19|20)\d{2}$")


def _norm_num(s):
    """数字归一化：去千分位、去尾随 0；年份返回 None（不参与继承判定）"""
    s = s.replace(",", "")
    if _YEAR_RE.match(s):
        return None
    try:
        f = float(s)
    except ValueError:
        return s
    return ("%g" % f)


def _numbers_outside_links(line):
    """取该行**不在 wikilink 内**的数字（链接文件名里的年份/编号不算正文数字）"""
    stripped = re.sub(r"!?\[\[[^\]]*\]\]", " ", line)
    stripped = re.sub(r"\[[^\]]*\]\([^)]*\)", " ", stripped)
    out = []
    for n in _NUM_PAT.findall(stripped):
        v = _norm_num(n)
        if v is not None:
            out.append(v)
    return out


def _section(body, names):
    """取第一个匹配 names 的二级标题到下一个二级标题之间的正文"""
    m = re.search(r"^##+\s*(%s)" % "|".join(names), body, re.M)
    if not m:
        return ""
    rest = body[m.end():]
    nxt = re.search(r"^##\s", rest, re.M)
    return rest[:nxt.start()] if nxt else rest


def check_evidence_inheritance(pages):
    """检查 7b: 证据标记继承（2026-09-25 新增，对应 QC 根因二）

    背景：QC 全库核查发现**头号失真类型**是
    「上游 source 页标了限定，下游 concept/topic 页把限定丢了，只留数字」，
    Q07 阶段实测命中率约 **65%**。根因是**机制缺位**。

    判据（**锚定具体数字**，而非「上游有没有 ⚠️」——后者无区分力，见上方注释）：
      1. 从每个 source 页正文中提取「**带限定标记的数字**」：
         在出现 `⚠️` 的**同一个块引用/列表项**内的数字
      2. 扫描 concept/topic 页正文中的数字
      3. 若某数字 `N` 出现在**该页引用的** source 的受限数字集合中，
         且本页**既无承接表述、该数字附近也无标记** → WARN

    ⚠️ 已知取舍：本检查**偏保守**——只在数字字符串完全一致时才报，
    因此会有漏报（漏报由 P4 人工「标记继承检查」补齐）。
    **宁可漏报，不可误报**：误报会让人彻底无视这条告警。
    """
    issues = []
    # —— 1. 每个 source 页：带限定标记的数字集合 ——
    restricted = {}     # 页面名 -> set(归一化数字)
    for rel, (fm, body, fp) in pages.items():
        if _page_type(rel) != "source":
            continue
        vals = set()
        # 以「行」为单位：同一行含 ⚠ 则该行的数字都算「带限定的」
        for line in body.split("\n"):
            if "⚠" not in line:
                continue
            vals.update(_numbers_outside_links(line))
        restricted[_page_name(rel)] = vals

    for rel, (fm, body, fp) in pages.items():
        ptype = fm.get("type", _page_type(rel))
        if ptype not in ("concept", "topic"):
            continue

        # —— 2. 本页引用的 source（仅 sources: 字段，避免把全文出链拉进来）——
        cited = set()
        srcs = fm.get("sources") or []
        if isinstance(srcs, str):
            srcs = [srcs]
        for s in srcs:
            nm = str(s).replace("\\|", "|").split("|")[0].strip()
            nm = nm.strip('"').strip("'").strip()
            if nm.startswith("[["):
                nm = nm[2:]
            if nm.endswith("]]"):
                nm = nm[:-2]
            nm = nm.replace("\\", "").split("/")[-1]
            if nm.endswith(".md"):
                nm = nm[:-3]
            cited.add(nm)

        pool = set()
        for nm in cited:
            pool |= restricted.get(nm, set())
        if len(pool) < 3:
            # 受限数字太少，判据不成立（避免在信息量不足的页上乱报）
            continue

        # —— 3. 本页是否已给出承接 ——
        # 页内已存在承接表述 → 视为整页已交代（不再逐数字报）
        if _HEDGE_PAT.search(body):
            continue

        # 正文中命中的受限数字（排除该行自身带 ⚠ 的；排除 wikilink 内的）
        hits = set()
        for line in body.split("\n"):
            if "⚠" in line:
                continue
            for n in _numbers_outside_links(line):
                if n in pool:
                    hits.add(n)

        if hits:
            shown = "、".join(sorted(hits)[:5])
            issues.append((rel, "WARN",
                           f"证据标记未继承：本页 {len(hits)} 个数字"
                           f"（{shown}）在引用的 source 中带限定标记，"
                           f"但本页无任何承接表述（QC 头号失真类型）"))
    return issues


def check_evidence_base(rel, fm, body, *a, **kw):
    """检查 7c: concept/topic 页 evidence_base 字段（2026-09-25 新增）

    `evidence_base` 是 QC 建议 1 定义的「证据承载体」字段
    （strong | mixed | single-source | secondhand）。缺该字段的综合页，
    下游无法判断这条结论能承载多强的断言。
    """
    issues = []
    if not isinstance(fm, dict):
        return issues
    if fm.get("type") not in ("concept", "topic"):
        return issues
    eb = fm.get("evidence_base")
    if eb is None or (isinstance(eb, str) and not eb.strip()):
        issues.append(("WARN", "concept/topic 页缺 evidence_base 字段（无法判证据承重）"))
    elif str(eb).strip().strip('"') not in ("strong", "mixed", "single-source", "secondhand"):
        issues.append(("WARN",
                       f"evidence_base 取值非规范: {eb!r}"
                       f"（应为 strong/mixed/single-source/secondhand）"))
    return issues


def check_index_consistency(pages):
    """检查 8: index.md 中列出的页面是否都存在"""
    issues = []
    index_path = os.path.join(K.WIKI, "index.md")
    if not os.path.exists(index_path):
        return [("index.md", "ERROR", "index.md not found")]
    text = K.read_text(index_path)
    # 提取所有 wikilink
    for m in re.finditer(r"\[\[([^\]\|#\\]+?)(?:\\?[#\|][^\]]*)?\]\]", text):
        link = m.group(1).strip()
        # 尝试匹配到实际文件
        # 格式可能是 entities/xxx 或 sources/xxx
        found = False
        for rel in pages:
            if link in rel or rel.endswith(link + ".md") or rel.endswith("/" + link + ".md"):
                found = True
                break
        # 也检查文件名直接匹配
        if not found:
            target = link.split("/")[-1]
            for rel in pages:
                if _page_name(rel) == target:
                    found = True
                    break
        if not found:
            issues.append(("index.md", "ERROR", f"index references non-existent page: [[{link}]]"))
    return issues

def check_duplicate_aliases(pages):
    """检查 9: 重复别名检测"""
    issues = []
    alias_to_pages = defaultdict(list)
    for rel, (fm, body, fp) in pages.items():
        aliases = fm.get("aliases", [])
        if isinstance(aliases, str):
            aliases = [aliases]
        for a in aliases:
            if a and str(a).strip():
                alias_to_pages[str(a).strip().lower()].append(_page_name(rel))
    for alias, page_list in alias_to_pages.items():
        if len(page_list) > 1:
            pages_str = ", ".join(page_list)
            issues.append((page_list[0], "WARN",
                          f"duplicate alias '{alias}' used by: {pages_str}"))
    return issues

def check_cross_reference_density(pages):
    """检查 10: 交叉引用密度分析"""
    issues = []
    concept_source_count = defaultdict(int)
    for rel, (fm, body, fp) in pages.items():
        if fm.get("type", "") != "source":
            continue
        outlinks = K.extract_outlinks(body)
        for link in outlinks:
            target = link.replace("\\|", "|").split("|")[0].split("#")[0].strip()
            target = target.replace("\\", "").split("/")[-1]
            concept_rel = f"concepts/{target}.md"
            if concept_rel in pages:
                concept_source_count[target] += 1
    # 识别知识密集区（>15 sources）和空白区（1 source）
    for concept, count in sorted(concept_source_count.items(), key=lambda x: -x[1]):
        if count > 15:
            issues.append((f"concepts/{concept}.md", "INFO",
                          f"knowledge-dense: linked by {count} sources"))
        elif count == 1:
            issues.append((f"concepts/{concept}.md", "INFO",
                          f"knowledge-sparse: linked by only {count} source"))
    return issues

def check_orphan_pages(pages, inbound_map):
    """检查 11: 孤立页面

    排除 wiki 根下的元页面（index/log/log_ops/log_insights）——它们由工具
    自动写、不参与页面互链，报「孤立」无意义。
    """
    issues = []
    META = {"index", "log", "log_ops", "log_insights"}
    for rel in pages:
        name = _page_name(rel)
        if name in META:
            continue
        if len(inbound_map.get(name, set())) == 0:
            issues.append((rel, "WARN", "orphan page: no inbound links"))
    return issues

def _normalize_mentioned(name, existing_names):
    """把日志里提到的页面写法归一成页面名；归一不了返回 None。

    日志中的页面有四种写法，早期版本只做 strip('`')，把下面四种全部误报：
      [[sources/x.md]]        带 wikilink 包裹
      [[sources/x]]           带 wikilink 包裹、无后缀
      wiki/sources/x.md       带 wiki/ 前缀与后缀
      sources/x.md            带目录前缀与后缀
    统一复用 _resolve_target 的剥离逻辑（去 [[ ]] / 去目录 / 去 .md / 查元页面），
    并额外容忍裸文件名——日志是自由文本，比对应宽松，只抓"确实不存在"。
    """
    t = name.strip().strip("`").strip()
    if t.startswith("[[") and t.endswith("]]"):
        t = t[2:-2]
    t = t.replace("\\|", "|").split("|")[0].split("#")[0].strip().replace("\\", "")
    # 去掉 wiki/ 前缀（日志里常带）
    if t.startswith("wiki/"):
        t = t[len("wiki/"):]
    base = t.split("/")[-1]
    if base.endswith(".md"):
        base = base[:-3]
    if base in existing_names:
        return base
    # 目录带错但文件名对：按页面名再兜一次
    if t in existing_names:
        return t
    if t.lower() in _META_PAGES:
        return t.lower()
    return None


def _live_log_paths():
    """日志文件，**活跃的在前**。

    🔴 2026-10-10 修：本模块两处日志检查都只读 `wiki/log.md`，而 CLAUDE.md
    §日志分离 已明确 `log.md` 是**冻结的历史存档**（"不再追加新内容"），
    新记录一律写 `log_ops.md`。后果有两层：
      · `--quick` 的「最近 N 天 ingest 的页面」始终锚在一个不再增长的文件上 ⇒
        新入库的页面**永远不会被 quick 选中**（quick 因此长期静默失效）；
      · 日志一致性检查只能反复扫存档，看不见新记录。
    ⇒ 现在两个日志都读（活跃优先），不再把流程绑在一个冻结文件上。
    """
    out = []
    for n in ("log_ops.md", "log.md"):
        p = os.path.join(K.WIKI, n)
        if os.path.exists(p):
            out.append((n, p))
    return out


def check_log_consistency(pages):
    """检查 12: 日志一致性（活跃日志 + 冻结存档都查）"""
    logs = _live_log_paths()
    if not logs:
        return [("log", "WARN", "log.md 与 log_ops.md 都不存在")]
    issues = []
    existing_names = set(_page_name(rel) for rel in pages)
    seen = set()
    for label, log_path in logs:
        text = K.read_text(log_path)
        # 提取所有 "新建页" 中提到的页面名
        mentioned_pages = set()
        for m in re.finditer(r"新建页\s*\d*[：:]\s*(.+)", text):
            names_str = m.group(1)
            for name in re.split(r"[、，,]", names_str):
                name = name.strip().strip("`").strip()
                if name:
                    mentioned_pages.add(name)
        for pname in mentioned_pages:
            if pname in seen:
                continue
            seen.add(pname)
            if _normalize_mentioned(pname, existing_names) is None:
                issues.append((label, "WARN",
                               f"{label} mentions page '{pname}' but file not found"))
    return issues

# ---------------------------------------------------------------- 入链图构建

def _build_inbound_map(pages):
    """构建入链映射 {page_name: set(linking_page_name)}"""
    name_set = set(_page_name(rel) for rel in pages)
    # 构建别名映射
    alias_map = {}
    for rel, (fm, body, fp) in pages.items():
        aliases = fm.get("aliases", [])
        if isinstance(aliases, str):
            aliases = [aliases]
        for a in aliases:
            if a and str(a).strip():
                alias_map[str(a).strip().lower()] = _page_name(rel)
    inbound = defaultdict(set)
    for rel, (fm, body, fp) in pages.items():
        src_name = _page_name(rel)
        outlinks = K.extract_outlinks(body)
        for link in outlinks:
            # 资源链接（[[raw/...]]、[[CLAUDE.md]] 等）不构成页面间的入链
            if _classify_link(link, name_set, alias_map, K.VAULT)[0] != "page":
                continue
            target = _resolve_target(link, name_set, alias_map)
            if target and target != src_name:
                inbound[target].add(src_name)
    return inbound

# ---------------------------------------------------------------- 页面选择

def _get_quick_pages(pages, args):
    """确定 quick lint 要检查的页面"""
    selected = {}
    if args.pages:
        for p in args.pages:
            p = p.strip()
            if p in pages:
                selected[p] = pages[p]
            else:
                # 尝试加 .md 后缀
                if not p.endswith(".md"):
                    p_md = p + ".md"
                else:
                    p_md = p
                if p_md in pages:
                    selected[p_md] = pages[p_md]
                else:
                    print(f"{C.YELLOW}[WARN]{C.RESET}  page not found: {p}")
        return selected
    if args.topic:
        topic_low = args.topic.lower()
        # 找 topic 页或相关 concept，然后找关联的 source
        for rel, (fm, body, fp) in pages.items():
            tags = fm.get("tags", [])
            if isinstance(tags, str):
                tags = [tags]
            tags_low = [str(t).lower() for t in tags]
            summary = str(fm.get("summary", "")).lower()
            if topic_low in tags_low or topic_low in summary or topic_low in rel.lower():
                selected[rel] = (fm, body, fp)
        # 也找链接到该 topic 的 source
        topic_name = None
        for rel in selected:
            if _page_type(rel) == "topic":
                topic_name = _page_name(rel)
                break
        if topic_name:
            for rel, (fm, body, fp) in pages.items():
                if _page_type(rel) != "source":
                    continue
                outlinks = K.extract_outlinks(body)
                for link in outlinks:
                    target = link.split("|")[0].split("#")[0].strip().split("/")[-1]
                    if target == topic_name:
                        selected[rel] = (fm, body, fp)
        return selected
    # 默认：最近 N 天 ingest 的页面。日志读**活跃的那一份**（log_ops.md 优先），
    # 否则 quick 会锚在冻结的 log.md 上，新页面永远选不中（见 _live_log_paths）。
    days = args.days or 7
    recent_names = []
    for _label, log_path in _live_log_paths():
        recent_names = _parse_log_dates(log_path, days)
        if recent_names:
            break
    if recent_names:
        existing = set(_page_name(rel) for rel in pages)
        for name in recent_names:
            if name in existing:
                for rel in pages:
                    if _page_name(rel) == name:
                        selected[rel] = pages[rel]
                        break
    if not selected:
        # 回退：取 updated 在最近 N 天内的页面
        cutoff = (datetime.now() - timedelta(days=days)).strftime("%Y-%m-%d")
        for rel, (fm, body, fp) in pages.items():
            updated = str(fm.get("updated", ""))
            if updated >= cutoff:
                selected[rel] = (fm, body, fp)
    return selected

# ---------------------------------------------------------------- 主逻辑

def run_quick(pages, args):
    """Quick Lint"""
    selected = _get_quick_pages(pages, args)
    if not selected:
        days = args.days or 7
        print(f"=== Quick Lint Report ===")
        print(f"没有找到最近 {days} 天内 ingest 的页面。")
        print(f"尝试用 --pages 或 --topic 指定页面。")
        return []

    name_set = _build_name_set(pages)
    alias_map = {}
    for rel, (fm, body, fp) in pages.items():
        aliases = fm.get("aliases", [])
        if isinstance(aliases, str):
            aliases = [aliases]
        for a in aliases:
            if a and str(a).strip():
                alias_map[str(a).strip().lower()] = _page_name(rel)
    inbound_map = _build_inbound_map(pages)

    days = args.days or 7
    print(f"{C.BOLD}=== Quick Lint Report ==={C.RESET}")
    print(f"Scanning {len(selected)} pages (last {days} days)...\n")

    all_issues = []
    for rel in sorted(selected):
        fm, body, fp = selected[rel]
        ptype = fm.get("type", _page_type(rel))
        page_issues = []
        # 检查 1: frontmatter
        page_issues.extend(check_frontmatter(rel, fm, body))
        # 检查 2: source 专项
        if ptype == "source":
            page_issues.extend(check_source_specific(rel, fm, body))
        # 检查 3: wikilink 有效性
        page_issues.extend(check_wikilinks(rel, fm, body, name_set, alias_map))
        # 检查 3b/3c: raw 回链写法 + YAML 可解析（2026-09-22 新增）
        page_issues.extend(check_raw_backlink_style(rel, fm, body))
        page_issues.extend(check_yaml_parseable(rel, fm, body))
        # 检查 7c: evidence_base（2026-09-25 新增）
        page_issues.extend(check_evidence_base(rel, fm, body))
        # 检查 4: 出度/入度
        page_issues.extend(check_degree(rel, fm, body, name_set, alias_map, inbound_map))
        # 检查 5: warning 标记
        page_issues.extend(check_warning_callout(rel, fm, body))

        if not page_issues:
            print(f"{_tag('OK')} {rel}: all checks passed")
            all_issues.append((rel, "OK", "all checks passed"))
        else:
            for level, msg in page_issues:
                print(f"{_tag(level)} {rel}: {msg}")
                all_issues.append((rel, level, msg))
        print()

    # 摘要
    errors = sum(1 for _, lv, _ in all_issues if lv == "ERROR")
    warns = sum(1 for _, lv, _ in all_issues if lv == "WARN")
    print(f"{C.BOLD}Summary:{C.RESET} {len(selected)} pages scanned, {errors} errors, {warns} warnings")
    return all_issues

def run_deep(pages, args):
    """Deep Lint — 全库全面、深入、细致的检查（含扩展检查族与可选修复）。"""
    print(f"{C.BOLD}=== Deep Lint Report ==={C.RESET}")
    print(f"Scanning all {len(pages)} pages...\n")

    name_set = _build_name_set(pages)
    alias_map = {}
    for rel, (fm, body, fp) in pages.items():
        aliases = fm.get("aliases", [])
        if isinstance(aliases, str):
            aliases = [aliases]
        for a in aliases:
            if a and str(a).strip():
                alias_map[str(a).strip().lower()] = _page_name(rel)
    inbound_map = _build_inbound_map(pages)
    all_issues = []

    # 对每个页面做 quick 检查
    print(f"{C.BOLD}--- Per-page checks ---{C.RESET}")
    for rel in sorted(pages):
        fm, body, fp = pages[rel]
        # wiki 根下的元页面（index/log*）不适用「页面规范」，只参与入链图构建
        if _page_name(rel) in ("index", "log", "log_ops", "log_insights"):
            continue
        ptype = fm.get("type", _page_type(rel))
        page_issues = []
        page_issues.extend(check_frontmatter(rel, fm, body))
        if ptype == "source":
            page_issues.extend(check_source_specific(rel, fm, body))
        page_issues.extend(check_wikilinks(rel, fm, body, name_set, alias_map))
        page_issues.extend(check_raw_backlink_style(rel, fm, body))
        page_issues.extend(check_yaml_parseable(rel, fm, body))
        page_issues.extend(check_evidence_base(rel, fm, body))
        page_issues.extend(check_degree(rel, fm, body, name_set, alias_map, inbound_map))
        if ptype == "source":
            page_issues.extend(check_warning_callout(rel, fm, body))
        for level, msg in page_issues:
            print(f"{_tag(level)} {rel}: {msg}")
            all_issues.append((rel, level, msg))

    # Deep 专项检查
    print(f"\n{C.BOLD}--- Structural checks ---{C.RESET}")

    # 0: 全库 frontmatter 可解析性（2026-09-22 新增，须在原始文本上做）
    for rel, level, msg in check_frontmatter_parse_all():
        print(f"{_tag(level)} {rel}: {msg}")
        all_issues.append((rel, level, msg))

    # 6: entity 深度
    for rel, level, msg in check_entity_depth(pages):
        print(f"{_tag(level)} {rel}: {msg}")
        all_issues.append((rel, level, msg))

    # 7: topic 覆盖
    for rel, level, msg in check_topic_coverage(pages):
        print(f"{_tag(level)} {rel}: {msg}")
        all_issues.append((rel, level, msg))

    # 7b: 证据标记继承（2026-09-25 新增，QC 根因二）
    for rel, level, msg in check_evidence_inheritance(pages):
        print(f"{_tag(level)} {rel}: {msg}")
        all_issues.append((rel, level, msg))

    # 8: index 一致性
    for rel, level, msg in check_index_consistency(pages):
        print(f"{_tag(level)} {rel}: {msg}")
        all_issues.append((rel, level, msg))

    # 9: 重复别名
    for rel, level, msg in check_duplicate_aliases(pages):
        print(f"{_tag(level)} {rel}: {msg}")
        all_issues.append((rel, level, msg))

    # 10: 交叉引用密度
    for rel, level, msg in check_cross_reference_density(pages):
        print(f"{_tag(level)} {rel}: {msg}")
        all_issues.append((rel, level, msg))

    # 11: 孤立页面
    for rel, level, msg in check_orphan_pages(pages, inbound_map):
        print(f"{_tag(level)} {rel}: {msg}")
        all_issues.append((rel, level, msg))

    # 12: 日志一致性
    for rel, level, msg in check_log_consistency(pages):
        print(f"{_tag(level)} {rel}: {msg}")
        all_issues.append((rel, level, msg))

    # ===== 扩展检查族（kb_lint_deep）=====
    ext_issues = []
    try:
        import kb_lint_deep as DEL
        print(f"\n{C.BOLD}--- Extended deep checks (A–F) ---{C.RESET}")
        for rel, level, code, msg, fix_id in DEL.run_deep_extended(pages, K.VAULT):
            tail = f"  {C.BOLD}[fixable:{fix_id}]{C.RESET}" if fix_id else ""
            print(f"{_tag(level)} {rel}: [{code}] {msg}{tail}")
            all_issues.append((rel, level, msg))
            ext_issues.append((rel, level, code, msg, fix_id))
    except Exception as e:
        print(f"{C.YELLOW}[WARN]{C.RESET} 扩展检查模块加载失败: {e}")

    # ===== 修复阶段（仅 --fix 时进入；默认干跑）=====
    if getattr(args, "fix", False) and ext_issues:
        _run_fix_phase(ext_issues, pages, apply=getattr(args, "apply", False))

    # 摘要
    errors = sum(1 for _, lv, _ in all_issues if lv == "ERROR")
    warns = sum(1 for _, lv, _ in all_issues if lv == "WARN")
    infos = sum(1 for _, lv, _ in all_issues if lv == "INFO")
    print(f"\n{C.BOLD}Summary:{C.RESET} {len(pages)} pages scanned, "
          f"{errors} errors, {warns} warnings, {infos} info")
    return all_issues


def _run_fix_phase(ext_issues, pages, apply=False):
    """执行可机械修复项。默认干跑；--apply 才落盘。

    遵循 CLAUDE.md §写盘脚本的额外铁律：
      · 写前用 kb_lib.split_frontmatter/join_frontmatter 同一解析器复核
      · 批量写盘前备份到 .qc_backup_YYYYMMDD/
      · 写后复算总量
    """
    import kb_lint_deep as DEL

    fixable = [x for x in ext_issues if x[4]]
    if not fixable:
        print(f"\n{C.BOLD}--- Fix phase ---{C.RESET}\n无可机械修复项。")
        return
    print(f"\n{C.BOLD}--- Fix phase ({'APPLY' if apply else 'DRY-RUN'}) ---{C.RESET}")
    applied = skipped = verify_ok = failed = 0
    for rel, _lv, code, msg, fix_id in fixable:
        fn = DEL.FIXERS.get(fix_id)
        if not fn:
            continue
        fp = None
        for r, (_fm, _b, p) in pages.items():
            if r == rel:
                fp = p
                break
        if not fp or not os.path.isfile(fp):
            print(f"  [skip] {rel}: 文件不存在")
            skipped += 1
            continue
        text = K.read_text(fp)
        fm_raw, body = K.split_frontmatter(text)
        result = fn(fm_raw, body, msg)
        if not result:
            print(f"  [skip] {rel}: 修复器无法安全判定（保持原样）")
            skipped += 1
            continue
        nfm, nbody = result
        new_text = K.join_frontmatter(nfm, nbody)
        # 写前复核：必须仍能解析出同样多的字段
        if not K.split_frontmatter(new_text)[0].strip():
            print(f"  [skip] {rel}: 复核失败（frontmatter 解析为空）")
            skipped += 1
            continue
        print(f"  [{'apply' if apply else 'dry '}] {rel}: [{code}] {msg[:60]}")
        if apply:
            # 备份 + 写盘 + **写后复算**，全部走 kb_lib 的共享实现。
            # 🔴 此前：docstring 声称"写后复算总量"，**代码里根本没有**——写完不看回读结果；
            #    备份还用 basename 拍平（wiki 各子目录间存在同名页 ⇒ 备份互相覆盖）；
            #    以 `newline=""` 直接写 ⇒ 把 CRLF 页整份翻成 LF（几千行噪声）。
            #    三件都已由 kb_lib.backup_file / write_text_verified 处理。
            bk = K.backup_file(fp)
            if not bk:
                print(f"  [skip] {rel}: 备份失败，拒绝写盘（铁律 3：没有回退点就不写）")
                skipped += 1
                continue
            ok, detail = K.write_text_verified(fp, new_text)
            if not ok:
                print(f"  [FAIL] {rel}: 写后复算不通过 —— {detail}")
                print(f"         已备份原件：{bk}（可据此还原）")
                failed += 1
                continue
            verify_ok += 1
        applied += 1
    print(f"  → 可修复 {len(fixable)}，{'已写盘' if apply else '可写盘'} {applied}，跳过 {skipped}"
          + (f"，写后复算通过 {verify_ok}，复算失败 {failed}" if apply else ""))
    if apply and applied:
        print(f"  → 备份: {K.backup_root()}")

def output_json(all_issues, pages_count):
    """JSON 格式输出"""
    # 清理消息中的控制字符
    _ctrl_re = re.compile(r'[\x00-\x1f\x7f]')
    report = {
        "pages_scanned": pages_count,
        "total_issues": len(all_issues),
        "errors": sum(1 for _, lv, _ in all_issues if lv == "ERROR"),
        "warnings": sum(1 for _, lv, _ in all_issues if lv == "WARN"),
        "info": sum(1 for _, lv, _ in all_issues if lv == "INFO"),
        "issues": [
            {"page": _ctrl_re.sub('', rel), "level": lv, "message": _ctrl_re.sub('', msg)}
            for rel, lv, msg in all_issues
        ]
    }
    print(json.dumps(report, ensure_ascii=False, indent=2))

# ---------------------------------------------------------------- 自检

def run_selftest():
    """校验器自检：用已知答案的样本反算链接解析器。

    背景：本库已有两次「计数器本身出错却被读成内容质量问题」的事故
    （batch_close.py 正则捕获组 bug、kb_lint.py 的 raw 回链误报）。
    凡是用正则/字符串计数做判定的校验器，都须能对已知答案反算一次。
    """
    pages = _load_all_pages()
    name_set = _build_name_set(pages)
    alias_map = {}
    for rel, (fm, body, fp) in pages.items():
        al = fm.get("aliases", [])
        al = [al] if isinstance(al, str) else al
        for a in al:
            if a and str(a).strip():
                alias_map[str(a).strip().lower()] = _page_name(rel)

    # 取一个真实存在页面名与真实存在的 raw 文件构造夹具
    any_page = sorted(name_set)[0] if name_set else None
    raw_files = []
    raw_dir = os.path.join(K.VAULT, "raw", "clippings")
    if os.path.isdir(raw_dir):
        raw_files = [f for f in sorted(os.listdir(raw_dir)) if f.endswith(".md")]

    cases = []  # (link, expect_kind)
    cases.append((f"concepts/{any_page}", "page"))
    cases.append((f"concepts/{any_page}.md", "page"))       # 带 .md 后缀
    cases.append(("[[" + any_page + "|显示文本]]", "page"))  # 别名形式
    cases.append(("index.md", "page"))                       # wiki 元页面
    cases.append(("log_ops.md", "page"))
    if raw_files:
        cases.append((f"raw/clippings/{raw_files[0]}", "file"))          # raw 回链（核心回归）
        cases.append((f"raw/clippings/{raw_files[0][:-3]}", "file"))     # 省略 .md
    cases.append(("raw/clippings/绝不存在-时代考焦-xyz.md", "broken"))    # 真错路径须仍报错
    cases.append(("CLAUDE.md", "file"))                                  # vault 根真实文件
    cases.append((f"concepts/{any_page}-绝不存在的页面", "broken"))        # 真错页面须仍报错

    print(f"{C.BOLD}=== kb_lint selftest ==={C.RESET}")
    print(f"fixtures: {len(cases)}  (name_set={len(name_set)} pages, raw/clippings={len(raw_files)} files)\n")
    failed = 0
    for raw_case in cases:
        link, expect = raw_case
        # 去掉夹具里的 [[ ]] 包裹，统一交给 _classify_link
        inner = link[2:-2] if link.startswith("[[") else link
        kind, resolved = _classify_link(inner, name_set, alias_map, K.VAULT)
        ok = (kind == expect)
        if not ok:
            failed += 1
        mark = f"{C.GREEN}PASS{C.RESET}" if ok else f"{C.RED}FAIL{C.RESET}"
        shown = inner if len(inner) <= 58 else inner[:55] + "..."
        print(f"  [{mark}] {shown:<60} expect={expect:<6} got={kind}"
              + (f" -> {resolved}" if resolved and kind != "broken" else ""))

    # —— 第二部分：证据标记继承（check_evidence_inheritance）————
    # 2026-09-25 新增。夹具**必须同时含正例与反例**——只测「该报的报了」
    # 会漏掉「不该报的报了」（假阳性会让人以后直接无视这条告警）。
    print(f"\n{C.BOLD}--- 证据标记继承夹具 ---{C.RESET}")
    inh_cases = _selftest_inheritance()
    for desc, expect_warn, got_warn in inh_cases:
        ok = expect_warn == got_warn
        if not ok:
            failed += 1
        mark = f"{C.GREEN}PASS{C.RESET}" if ok else f"{C.RED}FAIL{C.RESET}"
        print(f"  [{mark}] {desc:<44} expect={'WARN' if expect_warn else 'OK':<5} "
              f"got={'WARN' if got_warn else 'OK'}")
    total = len(cases) + len(inh_cases)

    print()
    if failed:
        print(f"{C.RED}{C.BOLD}SELFTEST FAILED{C.RESET}: {failed}/{total} cases wrong")
        return 1
    print(f"{C.GREEN}{C.BOLD}SELFTEST PASSED{C.RESET}: {total}/{total} cases correct")
    return 0


def _selftest_inheritance():
    """用内存夹具反算 check_evidence_inheritance，返回 (描述, 期望告警, 实际告警)。

    夹具不走磁盘：直接构造 pages 字典喂给函数，因此能在**不改全库**的前提下
    验证判定逻辑。这是本库第四次「计数器出错」事故后的强制纪律。

    ⚠️ 夹具设计要点（判据是「数字锚定」，不是「上游有没有 ⚠️」）：
      · 受限数字池至少要 **3 个**（函数内 `len(pool) < 3: continue`），
        否则夹具会因为「信息量不足」而全部不报、把真问题掩盖掉。
      · 必须同时含**正例**（该报）与**反例**（不该报）。
    """
    def mk(ptype, srcs, body, name="P"):
        fm = {"type": ptype, "sources": [f"[[sources/{s}]]" for s in srcs]}
        return (fm, body, f"x/{name}.md")

    # 两个 source 页，各自在带 ⚠ 的行里给出受限数字
    S1 = mk("source", [], "> ⚠️ 自报数字：准确率 87.5% 为作者自报\n"
                          "> ⚠️ 单源论断：提速 1200 倍仅本组报道\n"
                          "正文另提 3.3% 可执行率。\n", "S1")
    S2 = mk("source", [], "> ⚠️ 信息缺口：合成成功率 41% 未给对照\n"
                          "> ⚠️ 体裁提示：353 个配方来自评述文体\n"
                          "正文另提 68% 复现率。\n", "S2")
    # 无标记的 source（反例用）
    S3 = mk("source", [], "普通来源页，正文提到 87.5% 与 1200 倍，但无标记。\n", "S3")

    out = []

    # —— 正例：本页复述了受限数字，却无任何承接 ——
    pages = {
        "sources/S1.md": S1, "sources/S2.md": S2,
        "concepts/C1.md": mk("concept", ["S1", "S2"],
                             "该方法的准确率达到 87.5%，提速 1200 倍，"
                             "合成成功率为 41%。\n", "C1"),
    }
    out.append(("复述受限数字且无承接", True,
                bool(check_evidence_inheritance(pages))))

    # —— 反例 1：本页有承接表述 → 不报 ——
    pages = {
        "sources/S1.md": S1, "sources/S2.md": S2,
        "concepts/C1.md": mk("concept", ["S1", "S2"],
                             "该方法的准确率达到 87.5%（⚠️ 作者自报，无第三方核验），"
                             "提速 1200 倍。\n", "C1"),
    }
    out.append(("有承接表述", False,
                bool(check_evidence_inheritance(pages))))

    # —— 反例 2：数字不在受限集合里（未带标记的数字）→ 不报 ——
    pages = {
        "sources/S1.md": S1, "sources/S2.md": S2,
        "concepts/C1.md": mk("concept", ["S1", "S2"],
                             "该综述覆盖了 245 篇文献与 7 个数据库。\n", "C1"),
    }
    out.append(("数字不在受限集合内", False,
                bool(check_evidence_inheritance(pages))))

    # —— 反例 3：受限数字池 < 3，判据不成立 → 不报 ——
    pages = {
        "sources/S1.md": S1, "sources/S3.md": S3,
        "concepts/C1.md": mk("concept", ["S1", "S3"],
                             "准确率 87.5%。\n", "C1"),
    }
    out.append(("受限数字池不足 3 个", False,
                bool(check_evidence_inheritance(pages))))

    # —— 反例 4：source 页自身不参与该检查 ——
    pages = {
        "sources/S1.md": S1, "sources/S2.md": S2,
        "sources/S9.md": mk("source", ["S1", "S2"],
                            "本页复述 87.5% 与 41% 但自己也是 source。\n", "S9"),
    }
    out.append(("source 页不参与该检查", False,
                bool(check_evidence_inheritance(pages))))

    # —— 正例：topic 页同样适用 ——
    pages = {
        "sources/S1.md": S1, "sources/S2.md": S2,
        "topics/T1.md": mk("topic", ["S1", "S2"],
                           "汇总看，87.5% 的准确率与 41% 的成功率构成瓶颈。\n", "T1"),
    }
    out.append(("topic 页同样适用", True,
                bool(check_evidence_inheritance(pages))))

    # —— 反例 5：数字相等但本行自带 ⚠ → 不报 ——
    pages = {
        "sources/S1.md": S1, "sources/S2.md": S2,
        "concepts/C1.md": mk("concept", ["S1", "S2"],
                             "- ⚠️ 自报数字：87.5% 为其自报\n", "C1"),
    }
    out.append(("数字所在行自带标记", False,
                bool(check_evidence_inheritance(pages))))

    # —— 反例 6：命中数字只在 wikilink 内（年份/编号）→ 不报 ——
    #    2026-09-25 实测假阳性：`传输线模型` 因正文含 [[sources/2026-…]] 被报
    S4 = mk("source", [], "> ⚠️ 信息缺口：2026 年数据 41% 有疑\n"
                          "> ⚠️ 单源论断：87.5% 与 1200 倍仅本组\n"
                          "> ⚠️ 自报数字：3.3% 未核\n", "S4")
    pages = {
        "sources/S4.md": S4, "sources/S2.md": S2,
        "concepts/C1.md": mk("concept", ["S4", "S2"],
                             "见 [[sources/2026-某文献]] 与 [[sources/2019-另一篇]]。\n",
                             "C1"),
    }
    out.append(("命中数字只在 wikilink 内", False,
                bool(check_evidence_inheritance(pages))))

    # —— 反例 7：裸年份不算受限数字 → 不报 ——
    pages = {
        "sources/S4.md": S4, "sources/S2.md": S2,
        "concepts/C1.md": mk("concept", ["S4", "S2"],
                             "该方向自 2026 年起受到关注。\n", "C1"),
    }
    out.append(("裸年份不参与判定", False,
                bool(check_evidence_inheritance(pages))))

    # —— 正例：非年份的受限数字 + 无承接 → 仍应报 ——
    pages = {
        "sources/S4.md": S4, "sources/S2.md": S2,
        "concepts/C1.md": mk("concept", ["S4", "S2"],
                             "该体系覆盖率达到 87.5%，可执行率 3.3%。\n", "C1"),
    }
    out.append(("非年份受限数字无承接", True,
                bool(check_evidence_inheritance(pages))))

    return out


# ---------------------------------------------------------------- main

def main():
    ap = argparse.ArgumentParser(description="知识库分级 lint 检查")
    group = ap.add_mutually_exclusive_group(required=True)
    group.add_argument("--quick", action="store_true", help="快速检查最近 ingest 的页面")
    group.add_argument("--deep", action="store_true", help="全库深度检查")
    group.add_argument("--selftest", action="store_true", help="校验器自检（已知答案反算）")
    group.add_argument("--selftest-deep", action="store_true",
                       help="扩展检查模块自检（kb_lint_deep，已知答案反算）")
    ap.add_argument("--fix", action="store_true",
                    help="deep 模式：对可机械修复项执行修复（默认干跑，需配 --apply 落盘）")
    ap.add_argument("--apply", action="store_true",
                    help="deep --fix 时真正写盘（默认干跑）")
    ap.add_argument("--days", type=int, help="quick 模式：检查最近 N 天（默认 7）")
    ap.add_argument("--topic", type=str, help="quick 模式：指定主题关联的页面")
    ap.add_argument("--pages", nargs="+", help="quick 模式：指定页面路径")
    ap.add_argument("--json", action="store_true", help="JSON 格式输出")
    args = ap.parse_args()

    if args.selftest:
        return run_selftest()

    if args.selftest_deep:
        import kb_lint_deep as DEL
        return DEL.run_selftest()

    # 加载所有页面
    pages = _load_all_pages()
    if not pages:
        print("错误：未找到 wiki 页面，请检查 wiki/ 目录。")
        return 1

    # JSON 模式：抑制彩色输出，收集到 buffer
    old_stdout = None
    buf = None
    if args.json:
        old_stdout = sys.stdout
        buf = io.StringIO()
        sys.stdout = buf

    if args.quick:
        issues = run_quick(pages, args)
        pages_count = len(_get_quick_pages(pages, args))
    else:
        issues = run_deep(pages, args)
        pages_count = len(pages)

    # 恢复 stdout
    if args.json:
        sys.stdout = old_stdout
        output_json(issues, pages_count)

    return 0 if not any(lv == "ERROR" for _, lv, _ in issues) else 1

if __name__ == "__main__":
    sys.exit(main())
